function renderDashboardAcademicPerformance(){const root=document.getElementById('dashboardAcademic'),weeks=availableWeeks();if(!root||!weeks.length||!observationProgressReference.length||!smartAppRows.length)return;if(!dashboardAcademicState.week||!weeks.includes(dashboardAcademicState.week))dashboardAcademicState.week=weeks.at(-1);let rows=dashboardAcademicWaveRows(dashboardAcademicRows(dashboardAcademicState.week));rows.sort(dashboardAcademicState.sort==='high'?(a,b)=>(b.summary??-Infinity)-(a.summary??-Infinity)||a.branch.localeCompare(b.branch):dashboardAcademicState.sort==='low'?(a,b)=>(a.summary??Infinity)-(b.summary??Infinity)||a.branch.localeCompare(b.branch):dashboardAcademicState.sort==='change'?(a,b)=>(b.change??-Infinity)-(a.change??-Infinity)||a.branch.localeCompare(b.branch):(a,b)=>a.branch.localeCompare(b.branch));const trend=dashboardAcademicTrend(dashboardAcademicState.week),current=trend.at(-1)?.value;root.innerHTML=`<div class="dashboard-academic-head"><div><p class="eyebrow">ALL BRANCHES</p><h2>Academic performance summary</h2><p>Average of SQT, observation progress, and SmartApp usage.</p></div><div class="dashboard-academic-controls"><select id="dashboardAcademicWeek" aria-label="Select performance week">${weeks.map(week=>`<option value="${esc(week)}" ${week===dashboardAcademicState.week?'selected':''}>${esc(weekLabel(week))}</option>`).join('')}</select><select id="dashboardAcademicWave" aria-label="Filter branches by wave"><option value="all">All branches</option><option value="wave1to5" ${dashboardAcademicState.wave==='wave1to5'?'selected':''}>Wave 1–5</option><option value="wave6" ${dashboardAcademicState.wave==='wave6'?'selected':''}>Wave 6</option></select><select id="dashboardAcademicSort" aria-label="Sort academic performance"><option value="name">Branch A–Z</option><option value="high" ${dashboardAcademicState.sort==='high'?'selected':''}>Highest percentage</option><option value="low" ${dashboardAcademicState.sort==='low'?'selected':''}>Lowest percentage</option><option value="change" ${dashboardAcademicState.sort==='change'?'selected':''}>Biggest increase</option></select></div></div><div class="dashboard-academic-table"><table><thead><tr><th>Branch (${rows.length})</th><th>Summary percentage</th><th>Change</th><th>Status</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.branch)}</strong></td><td><span class="dashboard-score ${row.summary!==null&&row.summary<80?'low':''}">${row.summary===null?'—':`${row.summary.toFixed(1)}%`}</span></td><td class="delta ${row.change<0?'down':row.change>0?'up':''}">${row.change===null?'—':`${row.change>0?'▲':row.change<0?'▼':'—'} ${Math.abs(row.change).toFixed(1)} pts`}</td><td>${row.summary!==null&&row.summary>=80?'<span class="good">On track</span>':'<span class="warning">Needs attention</span>'}</td></tr>`).join('')}</tbody></table></div><section class="dashboard-academic-trend"><div><p class="eyebrow">ACADEMIC PERFORMANCE TREND</p><h3>Weekly overall performance</h3><p>Branch average across the three academic indicators.</p></div><aside><span>Current average</span><strong>${current===null||current===undefined?'—':`${current.toFixed(1)}%`}</strong></aside><div class="dashboard-trend-controls"><div class="filter-switch" role="group" aria-label="Academic trend date filter"><button class="${dashboardAcademicState.trendMode==='week'?'active':''}" data-dashboard-trend-mode="week">Filter by week</button><button class="${dashboardAcademicState.trendMode==='period'?'active':''}" data-dashboard-trend-mode="period">Filter by period</button></div><select id="dashboardTrendWeek" ${dashboardAcademicState.trendMode==='week'?'':'hidden'} aria-label="Select trend ending week">${weeks.map(week=>`<option value="${esc(week)}" ${week===dashboardAcademicState.trendWeek?'selected':''}>Up to ${esc(weekLabel(week))}</option>`).join('')}</select><div class="dashboard-trend-period" ${dashboardAcademicState.trendMode==='period'?'':'hidden'}><label>From <input id="dashboardTrendStart" type="date" value="${esc(dashboardAcademicState.trendStart)}"></label><label>To <input id="dashboardTrendEnd" type="date" value="${esc(dashboardAcademicState.trendEnd)}"></label><button id="applyDashboardTrendPeriod" class="control-button">Apply</button></div></div><div class="dashboard-trend-canvas">${dashboardAcademicTrendSvg(trend)}</div></section>`;cacheDashboardAcademic(root);root.querySelector('#dashboardAcademicWeek').addEventListener('change',event=>{dashboardAcademicState.week=event.target.value;renderDashboardAcademicPerformance()});root.querySelector('#dashboardAcademicWave').addEventListener('change',event=>{dashboardAcademicState.wave=event.target.value;renderDashboardAcademicPerformance()});root.querySelector('#dashboardAcademicSort').addEventListener('change',event=>{dashboardAcademicState.sort=event.target.value;renderDashboardAcademicPerformance()});root.querySelectorAll('[data-dashboard-trend-mode]').forEach(button=>button.addEventListener('click',()=>{dashboardAcademicState.trendMode=button.dataset.dashboardTrendMode;renderDashboardAcademicPerformance()}));root.querySelector('#dashboardTrendWeek')?.addEventListener('change',event=>{dashboardAcademicState.trendWeek=event.target.value;renderDashboardAcademicPerformance()});root.querySelector('#applyDashboardTrendPeriod')?.addEventListener('click',()=>{dashboardAcademicState.trendStart=root.querySelector('#dashboardTrendStart').value;dashboardAcademicState.trendEnd=root.querySelector('#dashboardTrendEnd').value;renderDashboardAcademicPerformance()})}
function dashboardTodayRows(rows,now=new Date){const today=day(now),minutes=now.getHours()*60+now.getMinutes(),expanded=rows.flatMap(row=>expandSessionDates(row,today,today)).filter(row=>row.classStatus.toLowerCase()==='active').map(row=>{const runtime=sessionRuntime(row,now),startMinutes=sessionStartMinutes(row.time),startsIn=startMinutes-minutes;return{...row,runtime,startMinutes,imminent:runtime==='upcoming'&&startsIn>=0&&startsIn<=60}});if(!expanded.some(row=>row.imminent)){const nextStart=Math.min(...expanded.filter(row=>row.runtime==='upcoming').map(row=>row.startMinutes));if(Number.isFinite(nextStart))expanded.forEach(row=>{if(row.runtime==='upcoming'&&row.startMinutes===nextStart)row.imminent=true})}const order={running:0,upcoming:1,passed:2};return expanded.sort((a,b)=>order[a.runtime]-order[b.runtime]||a.startMinutes-b.startMinutes||a.branch.localeCompare(b.branch))}
function witaDate(now=new Date){return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Makassar',weekday:'long',day:'numeric',month:'long'}).format(now)}
function witaTime(now=new Date){return`${new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Makassar',hour:'2-digit',minute:'2-digit',hour12:false}).format(now).replace(':','.')} WITA`}
function updateDashboardClock(){const clock=document.getElementById('dashboardClock');if(clock)clock.textContent=witaTime()}
function renderDashboardSessions(rows=sessionRows){const root=document.getElementById('dashboardSessions');if(!root)return;const today=dashboardTodayRows(rows),counts={running:0,upcoming:0,passed:0};today.forEach(row=>{if(row.runtime!=='upcoming'||row.imminent)counts[row.runtime]++});root.innerHTML=`<div class="dashboard-sessions-head"><div><p class="eyebrow">LIVE SCHEDULE</p><h2>Sessions today</h2><span>${witaDate()} <b id="dashboardClock">${witaTime()}</b></span></div><a href="#sessions">View all →</a></div><div class="dashboard-session-summary"><span class="running"><b>${counts.running}</b> Running</span><span class="upcoming"><b>${counts.upcoming}</b> Upcoming</span><span class="passed"><b>${counts.passed}</b> Done</span></div><div class="dashboard-session-list">${today.map(row=>{const later=row.runtime==='upcoming'&&!row.imminent,rowClass=later?'session-later':`session-${row.runtime}`,status=later?'Later today':row.runtime==='passed'?'Done':row.runtime;return`<article class="dashboard-session ${rowClass}"><div class="dashboard-session-time"><strong>${esc(row.time)}</strong><span>${status}</span></div><div class="dashboard-session-copy"><strong>${esc(row.branch)}</strong><span>${esc(row.className)}</span><small>${esc(row.teacher)}</small></div></article>`}).join('')||'<div class="dashboard-session-empty"><strong>No active sessions today.</strong><span>Today’s schedule will appear here when available.</span></div>'}</div>`}
async function initDashboardSessions(){const root=document.getElementById('dashboardSessions');try{const rows=sessionRows.length?sessionRows:makeSessionRows(await loadAllSessionRecords());renderDashboardSessions(rows);setInterval(updateDashboardClock,1000);setInterval(()=>{if(document.getElementById('dashboard')?.classList.contains('active'))renderDashboardSessions(rows)},30000)}catch(error){console.warn('Dashboard sessions could not load',error);if(root)root.innerHTML='<div class="dashboard-session-empty"><strong>Couldn’t load today’s sessions.</strong><span>Please refresh and try again.</span></div>'}}
