function initAcademicSticky(){const academic=document.getElementById('academic');if(!academic||academic.querySelector('.academic-sticky'))return;const title=academic.querySelector('.page-title'),tabs=academic.querySelector('.sqt-tabs');if(!title||!tabs)return;const shell=document.createElement('div');shell.className='academic-sticky';title.before(shell);shell.append(title,tabs);const dock=document.createElement('div');dock.className='academic-dock';dock.innerHTML=`<strong>Academic performance <span>/ SQT</span></strong><div>${[...tabs.querySelectorAll('button')].map(button=>`<span class="${button.classList.contains('active')?'active':''}">${esc(button.textContent)}</span>`).join('')}</div>`;document.body.append(dock);const style=document.createElement('style');style.textContent='.academic-sticky{position:relative;background:#f7f8fd;padding:1px 0 16px}.academic-dock{position:fixed;z-index:18;top:0;left:266px;width:calc(100% - 266px);height:58px;padding:0 34px;background:#f7f8fd;border-bottom:1px solid #e8e7f0;display:flex;align-items:center;justify-content:space-between;gap:22px;transform:translateY(-110%);transition:transform .18s ease;box-shadow:0 8px 18px #27234a0d}.academic-dock.visible{transform:translateY(0)}.academic-dock strong{font:700 17px Manrope;color:#201e2b}.academic-dock strong span{color:#6b5bdf}.academic-dock div{display:flex;gap:7px;overflow:hidden}.academic-dock div span{white-space:nowrap;border-radius:13px;background:#fff;padding:7px 10px;color:#85828e;font:700 11px "DM Sans"}.academic-dock div span.active{color:#fff;background:#6b5bdf}body.nav-hidden .academic-dock{left:0;width:100%}@media(max-width:1129px){.academic-dock{left:220px;width:calc(100% - 220px)}}@media(max-width:760px){.academic-dock{left:0;width:100%;padding:0 18px;height:54px}.academic-dock div span:not(.active){display:none}.academic-dock strong{font-size:14px}}';document.head.append(style);const update=()=>dock.classList.toggle('visible',window.scrollY>shell.offsetTop+80);window.addEventListener('scroll',update,{passive:true});update()}
async function loadObservationLinks(){const response=await fetch(gvizUrl(sources.academic,'Link Observasi'));if(!response.ok)throw Error('Link Observasi unavailable');return tableRows(parseGViz(await response.text())).rows}
async function loadTeacherRecords(){const response=await fetch(gvizUrl(observationSource,'Teachers'));if(!response.ok)throw Error('Teachers source unavailable');return records(parseGViz(await response.text()))}
async function loadObservationProgressReference(){const response=await fetch(gvizGidUrl(sources.academic,observationProgressGid));if(!response.ok)throw Error('Observation progress summary unavailable');return records(parseGViz(await response.text())).filter(row=>row.Branch&&row.Branch!=='Total')}
async function loadObservationRecords(){const[response,linkRows,teacherRows,progressRows]=await Promise.all([fetch(gvizUrl(observationSource,'OBSERVATION')),loadObservationLinks().catch(()=>[]),loadTeacherRecords(),loadObservationProgressReference().catch(()=>[])]);if(!response.ok)throw Error('Observation sheet unavailable');observationLinks=makeObservationLinks(linkRows);observationProgressReference=progressRows;observationRoles=new Map;inactiveObservationTeachers=new Set;observationTeacherRoster=makeObservationTeacherRoster(teacherRows);return records(parseGViz(await response.text()))}
function teacherKey(center,teacher){return`${branchKey(center)}|${String(teacher||'').trim().toLowerCase()}`}
function makeInactiveTeachers(rows){return new Set(rows.filter(row=>String(row['Input manual Teaching Status']||'').trim().toLowerCase()==='inactive').map(row=>String(row['Teacher Input manual Name']||'').trim().toLowerCase()).filter(Boolean))}
function makeObservationLinks(rows){const links=new Map;rows.slice(1).forEach(row=>{const center=String(row[0]||'').trim();if(!center)return;links.set(branchKey(center),{Q1:String(row[1]||'').trim(),Q2:String(row[2]||'').trim(),Q3:String(row[3]||'').trim(),Q4:String(row[4]||'').trim()})});return links}
function quarterFromDate(date){return date?`Q${Math.floor(date.getMonth()/3)+1}`:''}
function observationLink(center,role,quarter,sourceRole=''){const isCoach=/\bmtc\b|mt\s*coach/i.test(`${role} ${sourceRole}`),links=isCoach?(observationLinks.get(branchKey('MT Coach Indonesia Timur'))||observationLinks.get(branchKey('MTC Indonesia Timur'))):observationLinks.get(branchKey(center));return links?.[quarter]||''}
function makeObservationRoles(raw){const roles=new Map;raw.forEach(row=>{const center=String(row['Data FTE: Center']||'').trim(),teacher=String(row['TEACHER DATABASE [INDONESIA TIMUR] 2026 Name']||'').trim(),role=String(row['Folder All Manual: Role']||'').trim();if(!teacher||!role)return;roles.set(teacherKey(center,teacher),role);const byName=`|${teacher.toLowerCase()}`;if(!roles.has(byName))roles.set(byName,role)});return roles}
function makeObservationTeacherRoster(raw){const unique=new Map;raw.forEach(row=>{const center=String(row['Input Manual Center']||'').trim(),teacher=String(row['Teacher Input manual Name']||'').trim(),role=String(row['Input manual Position/\nRole']||'').trim(),teachingStatus=String(row['Input manual Teaching Status']||'').trim().toUpperCase();if(!center||!teacher||!['MT Local','MT Coach'].includes(role)||teachingStatus==='INACTIVE')return;unique.set(teacherKey(center,teacher),{center,teacher,role})});return[...unique.values()]}
