function enhanceSmartOverall(){const panel=document.getElementById('smartAppPanel'),shell=panel?.querySelector('.smart-table-shell');if(!panel||!shell)return;const rows=aggregateSmartApp(selectedSmartAppRows()),current=smartUsageTotals(selectedSmartAppRows()),layout=document.createElement('div'),aside=document.createElement('aside'),label=smartAppState.mode==='week'?weekLabel(smartAppState.week):'Selected period',high=[...rows].sort((a,b)=>b.pct-a.pct||a.branch.localeCompare(b.branch)).slice(0,3),low=[...rows].sort((a,b)=>a.pct-b.pct||a.branch.localeCompare(b.branch)).slice(0,3),ranking=items=>items.map((row,index)=>`<li><span>${index+1}. ${esc(row.branch)}</span><b style="color:${smartUsageColor(row.pct)}">${row.pct.toFixed(1)}%</b></li>`).join('');layout.className='smart-table-layout';aside.className='smart-glance';shell.before(layout);layout.append(shell,aside);aside.innerHTML=`<p class="eyebrow">SMARTAPP USAGE AT A GLANCE</p><h3>${esc(label)}</h3><div class="smart-glance-stat"><span>Overall usage</span><strong style="color:${smartUsageColor(current.pct??0)}">${(current.pct??0).toFixed(1)}%</strong></div><div class="smart-glance-stat"><span>Connected classes</span><strong>${current.connected} / ${current.scheduled}</strong></div><p class="smart-glance-definition"><strong>Definition</strong>Each unique class counts once per week and is connected when at least one scheduled session has an activity score.</p><p class="smart-glance-target">Target: <strong>80%</strong></p><div class="smart-glance-rankings"><section><h4>Top 3 usage</h4><ol>${ranking(high)}</ol></section><section><h4>Bottom 3 usage</h4><ol>${ranking(low)}</ol></section></div>`;const trend=document.createElement('section'),analysis=document.createElement('section');trend.className='smart-trend-section';analysis.className='smart-analysis';panel.append(trend,analysis);renderSmartTrend(trend);renderSmartAnalysis(analysis,rows,current)}
