function setView(v){const available=new Set([...document.querySelectorAll('.view')].map(view=>view.id));if(!available.has(v))v='dashboard';localStorage.setItem('acops-active-view',v);preserveLiveStatus();initLayoutControls();fixDockOffset();hideGlobalSearch();document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===v));document.querySelectorAll('.nav-link').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='academic'){updateSqtDescription();initAcademicSticky();initObservationDetails();initSmartAppUsage();watchObservationRoles();watchAcademicDock()}if(v==='sessions')initSessions();if(v==='center')renderLinkBoard()}
function renderLinkBoard(){const t=activeTables.center;if(!t?.rows?.length)return;const u=t.headers.findIndex(h=>/link|url/i.test(h)),n=t.headers.findIndex(h=>/name|title|resource/i.test(h));if(u<0)return;document.getElementById('linkBoard').innerHTML=t.rows.filter(r=>r[u]).slice(0,9).map(r=>`<a class="resource-link" href="${esc(r[u])}" target="_blank" rel="noreferrer"><small>RESOURCE</small>${esc(r[n]||r[u])}<span>↗</span></a>`).join('')}
let sqtSearchTimer=0,sqtSearchOnly=false;
const fullSqtChartRender=renderChart;
renderChart=function(rows){if(sqtSearchOnly){try{prepareSqtTable(rows);formatSessionColumns();renderSqtRankings(rows);balanceSqtLayout();balanceCollapsedTable();labelSqtChange()}catch(error){console.warn('SQT table layout could not be enhanced',error)}return}return fullSqtChartRender(rows)};
document.getElementById('sqtSearch').addEventListener('input',event=>{event.stopImmediatePropagation();sqtState.search=event.target.value;clearTimeout(sqtSearchTimer);sqtSearchTimer=setTimeout(()=>{sqtSearchOnly=true;renderSqt();sqtSearchOnly=false},70)},true);
Object.entries(sources).forEach(([k,s])=>{const l=document.getElementById(`${k}Link`);if(l)l.href=sheetUrl(s)});document.getElementById('sessionsLink').href=`https://docs.google.com/spreadsheets/d/${allSessionsSource.id}/edit?gid=${allSessionsSource.gid}#gid=${allSessionsSource.gid}`;makeDashboard();['operations','center'].forEach(buildTabs);initSqt();document.getElementById('sqtWeek').addEventListener('change',e=>{sqtState.week=e.target.value;renderSqt()});document.querySelectorAll('[data-filter-mode]').forEach(b=>b.addEventListener('click',()=>{sqtState.mode=b.dataset.filterMode;document.querySelectorAll('[data-filter-mode]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('weekFilter').hidden=sqtState.mode!=='week';document.getElementById('periodFilter').hidden=sqtState.mode!=='period';renderSqt()}));document.getElementById('applyPeriod').addEventListener('click',()=>{sqtState.start=document.getElementById('sqtStart').value;sqtState.end=document.getElementById('sqtEnd').value;renderSqt()});document.getElementById('sqtSearch').addEventListener('input',e=>{sqtState.search=e.target.value;renderSqt()});document.getElementById('sqtSort').addEventListener('change',e=>{sqtState.sort=e.target.value;renderSqt()});document.getElementById('exportSqt').addEventListener('click',exportSqt);window.addEventListener('hashchange',()=>setView(location.hash.slice(1)||localStorage.getItem('acops-active-view')||'dashboard'));setView(location.hash.slice(1)||localStorage.getItem('acops-active-view')||'dashboard');
